questionvariables.text:
/*STA 141 week2 quizes*/
correct_answer:rand_selection([
[1, true, "It does not possess the desired algebraic property"],
[2, true, "It is uniquely defined"],
[3, true, "It is least affected by fluctuations of the sample"]
], 1);
incorrect_answers:rand_selection([
[4, false, "It is affected by extreme values"],
[5, false, "It cannot be computed in grouped data with open-ended class intervals"],
[6, false, "It does not deal with qualitative data that cannot be expressed numerically"],
[7, false, "It cannot be computed for grouped data in the cases of open classes
"]], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
